import React, { useEffect, useRef, useState } from 'react';
import './App.css';

const FIELD_NAMES = ['name', 'email', 'message'] as const;
type FieldName = (typeof FIELD_NAMES)[number];
type Fields = Record<FieldName, string>;

const EMPTY_FIELDS: Fields = { name: '', email: '', message: '' };
const NOTHING_TOUCHED: Record<FieldName, boolean> = { name: false, email: false, message: false };
const ALL_TOUCHED: Record<FieldName, boolean> = { name: true, email: true, message: true };

const TIME_LIMIT_MS = 2000;

function validate(fields: Fields): Partial<Record<FieldName, string>> {
  const name = fields.name.trim();
  const email = fields.email.trim();
  const message = fields.message.trim();

  return {
    name: name ? undefined : 'Name is required.',
    email: !email
      ? 'Email is required.'
      : /\S+@\S+\.\S+/.test(email)
        ? undefined
        : 'Enter a valid email address.',
    message: !message
      ? 'Message is required.'
      : message.length >= 10
        ? undefined
        : 'Message should be at least 10 characters.'
  };
}

async function sendMessage(fields: Fields, signal: AbortSignal): Promise<void> {
  // The live preview has no network, so it falls back to a short fake request.
  if (typeof fetch !== 'function') {
    await new Promise<void>((resolve, reject) => {
      const timerId = window.setTimeout(resolve, 600);
      signal.addEventListener('abort', () => {
        window.clearTimeout(timerId);
        reject(new DOMException('Request cancelled', 'AbortError'));
      });
    });
    return;
  }

  const response = await fetch('https://jsonplaceholder.typicode.com/posts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name: fields.name.trim(),
      email: fields.email.trim(),
      message: fields.message.trim()
    }),
    signal
  });

  if (!response.ok) {
    throw new Error('Request failed');
  }
}

export default function App() {
  const [fields, setFields] = useState<Fields>(EMPTY_FIELDS);
  const [touched, setTouched] = useState(NOTHING_TOUCHED);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const requestRef = useRef<{ controller: AbortController; timerId: number } | null>(null);

  const errors = validate(fields);

  useEffect(() => {
    return () => {
      if (!requestRef.current) return;
      window.clearTimeout(requestRef.current.timerId);
      requestRef.current.controller.abort();
    };
  }, []);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (requestRef.current) return;

    setSuccessMessage('');
    setErrorMessage('');
    setTouched(ALL_TOUCHED);

    const firstInvalid = FIELD_NAMES.find((field) => errors[field]);
    if (firstInvalid) {
      document.getElementById(firstInvalid)?.focus();
      return;
    }

    const controller = new AbortController();
    let timedOut = false;
    const timerId = window.setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, TIME_LIMIT_MS);
    requestRef.current = { controller, timerId };
    setIsSubmitting(true);

    try {
      await sendMessage(fields, controller.signal);
      setSuccessMessage('Your message has been sent. Thank you!');
      setFields(EMPTY_FIELDS);
      setTouched(NOTHING_TOUCHED);
    } catch {
      // An abort without the time limit means the component is gone.
      if (controller.signal.aborted && !timedOut) return;
      setErrorMessage(
        timedOut ? 'The server took too long. Please try again.' : 'Something went wrong. Please try again.'
      );
    } finally {
      window.clearTimeout(timerId);
      requestRef.current = null;
      setIsSubmitting(false);
    }
  };

  const fieldProps = (field: FieldName) => {
    const invalid = touched[field] && !!errors[field];
    return {
      id: field,
      value: fields[field],
      'aria-invalid': invalid,
      'aria-describedby': invalid ? `${field}-error` : undefined,
      onChange: (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        setSuccessMessage('');
        setFields((current) => ({ ...current, [field]: event.target.value }));
      },
      onBlur: () => setTouched((current) => ({ ...current, [field]: true }))
    };
  };

  const fieldError = (field: FieldName) =>
    touched[field] && errors[field] ? (
      <p id={`${field}-error`} className="error">{errors[field]}</p>
    ) : null;

  return (
    <main className="main">
      <section className="section">
        <h1>Contact Us</h1>

        <form className="panel" noValidate onSubmit={handleSubmit}>
          <div className="field">
            <label htmlFor="name">Name</label>
            <input type="text" {...fieldProps('name')} />
            {fieldError('name')}
          </div>

          <div className="field">
            <label htmlFor="email">Email</label>
            <input type="email" {...fieldProps('email')} />
            {fieldError('email')}
          </div>

          <div className="field">
            <label htmlFor="message">Message</label>
            <textarea rows={4} {...fieldProps('message')} />
            {fieldError('message')}
          </div>

          <button type="submit" className="primary" disabled={isSubmitting}>
            {isSubmitting ? 'Sending…' : 'Send message'}
          </button>

          {successMessage && <p className="success" role="status">{successMessage}</p>}
          {errorMessage && <p className="error" role="alert">{errorMessage}</p>}
        </form>
      </section>
    </main>
  );
}

